std::copy(InputIterator first, InputIterator last, OutputIterator d);

// Using std::front_inserter with a container:
std::copy(source_begin, source_end, std::front_inserter(container));

code_example:
#include <iostream>
#include <list>
#include <vector>
#include <algorithm>

int main() {
    std::vector<int> v = {1, 2, 3, 44, 55};
    std::list<int> lst;
    // Insert elements from vector into list in reverse order using front_inserter
    std::copy(v.begin(), v.end(), std::front_inserter(lst));
    // Output the list contents
    for (int n : lst) {
        std::cout << n << ' ';
    }
    std::cout << '\n';
    return 0;
}
